function walk(value,fn,path='') {if(!value||typeof value!=='object')return;for(const [key,x]of Object.entries(value)){const site=path+'/'+escape(key);fn(value,key,x,site);const literal=key==='value'&&value.op==='constant'||['locals','variables','default','initialState','values','stateSchema','resultSchema','localSchema'].includes(key)||key==='value'&&value.type==='variable'||key==='value'&&['set','return'].includes(value.kind)&&!x?.op;if(!literal)walk(x,fn,site);}}
