function safeData(value,depth=0,budget={remaining:PACKAGE_LIMITS.values}) {if(--budget.remaining<0||depth>PACKAGE_LIMITS.depth)throw Error('Пакет слишком сложный.');if(['function','symbol','bigint','undefined'].includes(typeof value))throw Error('Пакету нужны сериализуемые данные.');if(typeof value==='number'&&!Number.isFinite(value))throw Error('Некорректное число в пакете.');if(!value||typeof value!=='object')return;for(const [k,v]of Object.entries(value)){if(unsafe.has(k)||['script','scripts','javascript','install','postinstall','code'].includes(k))throw Error('Код и установочные скрипты запрещены в авторском пакете.');safeData(v,depth+1,budget);}}
