export const packageCapabilities=()=>[...capabilityDefinitions().map(d=>({id:'capability.'+d.id,version:d.version})),...operationDefinitions().map(d=>({id:'operation.'+d.id,version:d.version})),...Object.keys(GAME_COMMANDS).map(id=>({id:'command.'+id,version:1})),...Object.keys(TYPES).map(id=>({id:'action.'+id,version:1})),{id:'component.resources',version:1},{id:'behavior.tree',version:1},{id:'mechanic.components',version:1},{id:'mechanic.javascript',version:1},{id:'mechanic.serialized-fields',version:1},{id:'function.graph',version:1},{id:'function.typed-graph',version:1},{id:'mechanic.rules',version:1}];
async function digest(data){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',data))].map(v=>v.toString(16).padStart(2,'0')).join('');}
function bytes64(data){const bytes=new Uint8Array(data);let result='';for(let i=0;i<bytes.length;i+=8192)result+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(result);}
function unbase64(s){if(typeof s!=='string'||s.length>140000000||s.length%4!==0||!/^[A-Za-z0-9+/]*={0,2}$/.test(s))throw Error('Ресурс повреждён или слишком большой.');return Uint8Array.from(atob(s),c=>c.charCodeAt(0));}
function mediaType(type){if(!/^(audio\/(mpeg|mp3|wav|x-wav|ogg|webm)|image\/(png|jpeg|webp)|model\/gltf(-binary|\+json))$/.test(type))throw Error('Неподдерживаемый ресурс: '+type);return type;}
function inferredType(blob,url){const extension=url.split(/[?#]/)[0].split('.').at(-1).toLowerCase();return ({glb:'model/gltf-binary',gltf:'model/gltf+json',mp3:'audio/mpeg',wav:'audio/wav',ogg:'audio/ogg',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp'})[extension]||blob.type;}
const modelExtensions=new Set(['KHR_lights_punctual','KHR_materials_unlit','KHR_materials_emissive_strength','KHR_materials_clearcoat','KHR_materials_dispersion','KHR_materials_iridescence','KHR_materials_sheen','KHR_materials_transmission','KHR_materials_volume','KHR_materials_ior','KHR_materials_specular','EXT_materials_bump','KHR_materials_anisotropy','EXT_texture_webp','EXT_texture_avif','EXT_mesh_gpu_instancing','KHR_texture_transform','KHR_mesh_quantization']);
function modelUris(data,type){let model;if(type==='model/gltf+json')model=JSON.parse(new TextDecoder().decode(data));else if(type==='model/gltf-binary'){const view=new DataView(data.buffer,data.byteOffset,data.byteLength);if(view.byteLength<20||view.getUint32(0,true)!==0x46546c67||view.getUint32(4,true)!==2||view.getUint32(8,true)!==data.byteLength||view.getUint32(16,true)!==0x4e4f534a)throw Error('Повреждена модель GLB.');const size=view.getUint32(12,true);if(size>data.byteLength-20)throw Error('Повреждён размер модели GLB.');model=JSON.parse(new TextDecoder().decode(data.subarray(20,20+size)));}if(model){safeData(model);if(model.asset?.version!=='2.0')throw Error('Неподдерживаемая версия модели.');for(const id of model.extensionsRequired||[])if(!modelExtensions.has(id))throw Error('Модели нужна неподдерживаемая возможность: '+id);}return model;}
export async function portableAsset(blob,url,readAsset){const type=mediaType(inferredType(blob,url));let data=new Uint8Array(await blob.arrayBuffer());const model=modelUris(data,type);if(model){for(const entry of [...model.buffers||[],...model.images||[]])if(entry.uri&&!entry.uri.startsWith('data:')){if(type==='model/gltf-binary')throw Error('Модель GLB содержит внешний ресурс. Сохраните её с встроенными ресурсами.');const dependency=new URL(entry.uri,new URL(url,globalThis.location?.href||'http://localhost/')).href;const resource=await readAsset(dependency);entry.uri='data:'+(resource.type||'application/octet-stream')+';base64,'+bytes64(await resource.arrayBuffer());}if(type==='model/gltf+json')data=new TextEncoder().encode(JSON.stringify(model));}return {type,data};}


