      if(['args','conditionArgs'].includes(key)&&value&&typeof value==='object'){const f=project.functions.find(f=>f.id===parent[key==='args'?'functionId':'conditionFunctionId']);for(const param of f?.parameters||[])if(['item','event','function'].includes(param.referenceType)&&value[param.name])include(value[param.name]);}
