  const signalIds=new Set((copy.content.gameplay?.signals||[]).map(s=>s.id));
  remapTypedReferences(copy.content,ids);
  for(const r of copy.content.logicResources||[])if(r.kind==='component.code'){r.approved=false;r.status='review';}
  for(const f of copy.content.functions||[])if(f.mechanicScript)f.mechanicScript.approved=false;
  const variableIds=new Map();for(const name of Object.keys(copy.content.variables||{})){let fresh=name,index=2;while(Object.hasOwn(next.variables,fresh)||[...variableIds.values()].includes(fresh))fresh=name+'_'+index++;variableIds.set(name,fresh);if(name!==fresh)renames.push(name+' → '+fresh);}
  walk(copy.content,(parent,key,value)=>{if(parent===copy.content.ui&&ids.has(value))parent[key]=ids.get(value);if(['equipment','functions','handlers','interactionEvents'].includes(key)&&value&&typeof value==='object'&&!Array.isArray(value))for(const slot of Object.keys(value))if(ids.has(value[slot]))value[slot]=ids.get(value[slot]);if(Array.isArray(value)&&referenceArrays.has(key))parent[key]=value.map(id=>ids.get(id)||id);if(typeof value!=='string')return;if(parent.kind==='gate'&&key==='signal'&&ids.has(value))parent[key]=ids.get(value);if(['type','signal','when','trigger'].includes(key)&&signalIds.has(value)&&ids.has(value))parent[key]=ids.get(value);if((idKeys.has(key)&&!(key==='id'&&(parent.kind==='reference'||parent.scopes||Object.hasOwn(parent,'parameters')&&Object.hasOwn(parent,'version')&&!parent.name))||key==='target'&&parent.type!=='variable'||key==='source')&&ids.has(value))parent[key]=ids.get(value);if(['path','output'].includes(key)&&value.startsWith('global.')){const name=value.split('.')[1];if(variableIds.has(name))parent[key]='global.'+variableIds.get(name)+value.slice(('global.'+name).length);}if((key==='target'&&parent.type==='variable'||variableKeys.has(key))&&variableIds.has(value))parent[key]=variableIds.get(value);if(key==='path'&&parent.source==='variable'){const name=value.split('.')[0];if(variableIds.has(name))parent[key]=variableIds.get(name)+value.slice(name.length);}});
  for(const d of copy.content.gameplay?.mechanicDefinitions||[])d.id=ids.get(d.id)||d.id;
  walk(copy.content,(parent,key,value)=>{if(['actors','transforms','actionOverrides','targetBindings','interactionEvents','positions','timelineLayout','storyLayout','graphLayout','variableLayout'].includes(key)&&value&&typeof value==='object'&&!Array.isArray(value)){for(const old of Object.keys(value))if(ids.has(old)){value[ids.get(old)]=value[old];delete value[old];}}});
  for(const w of copy.content.widgets||[])if(w.css)w.css=w.css.replace(/(\[data-element\s*=\s*['"])([^'"]+)(['"]\])/g,(_,a,id,b)=>a+(ids.get(id)||id)+b);
  // Reference sites identify original array positions; bindings are applied after local ID remapping.
  for(const ref of copy.references){const {parent,key}=location(copy,ref.at),input=copy.inputs.find(i=>i.id===ref.inputId);let id=bindings[ref.inputId];if(!ref.typed&&input.nativeReference&&input.type==='variable'&&id)id=variableKey(project,id);if(ref.typed){if(id)parent[key]=reference(copy.inputs.find(i=>i.id===ref.inputId).type,id);else delete parent[key];continue;}if(ref.key){const value=parent[key];delete parent[key];parent[id]=value;}else if(ref.variablePath){let value=project.variables[id];for(const member of ref.memberPath){if(!value||!Object.hasOwn(value,member))throw Error('Поле переменной отсутствует: '+member);value=value[member];}parent[key]=[...(ref.widgetPath?[]:['global']),id,...ref.memberPath].join('.');}else parent[key]=id||'';}
  visitTypedReferences(copy.content,r=>{if(r.type==='project'&&r.id==='package-project')r.id=next.id;});
  walk(copy.content,(parent,key,value)=>{if(parent.kind==='project'&&key==='id')parent[key]=next.id;if(typeof value==='string'&&value.startsWith('package-asset:')){const a=copy.assets.find(a=>a.id===value.slice(14));parent[key]='data:'+a.mediaType+';base64,'+a.data;}});
