  walk(copy.content,(parent,key,value)=>{if(key==='default'&&['item','event','function','object','scene'].includes(parent.referenceType)&&ids.has(value))parent[key]=ids.get(value);if(['args','conditionArgs'].includes(key)&&value&&typeof value==='object'){const f=copy.content.functions?.find(f=>f.id===parent[key==='args'?'functionId':'conditionFunctionId']);for(const a of f?.parameters||[])if(['item','event','function','object','scene'].includes(a.referenceType)&&ids.has(value[a.name]))value[a.name]=ids.get(value[a.name]);}});
  const append=(path,records)=>{if(!records)return;const destination=targetArray(next,path);for(const r of records){if(path==='logicResources'){const base=r.path;let index=2;while(destination.some(x=>x.path===r.path))r.path=base.replace(/(\.[^/.]+)?$/, ' '+index+++'$1');if(r.path!==base)renames.push(base+' → '+r.path);}if(r.name){const existing=new Set(destination.map(x=>x.name));let name=r.name,i=2;while(existing.has(name))name=r.name+' ('+i+++')';if(name!==r.name){renames.push(r.name+' → '+name);r.name=name;}}destination.push(r);}};
  for(const [path,records]of Object.entries(collections({...copy.content,gameplay:copy.content.gameplay||defaultGameplay()})))append(path,records);
  append('gameplay/mechanics',copy.content.gameplay?.mechanics);
  for(const inv of copy.content.gameplay?.inventories||[]){if(inventoryConfig(next.gameplay,inv.owner.id))throw Error('У владельца уже подключён инвентарь. Выберите другого владельца.');next.gameplay.inventories.push(inv);}
